// Durable accounts and recovery. Credentials are sent only to the selected game server.
export function mountAccountUI(container,{endpoint,getToken,setIdentity,onLogout}={}){
 const panel=document.createElement('details');panel.className='game-preferences account-panel';panel.innerHTML=`<summary>Save or recover your career</summary><p>Create an account to keep your progress across browsers. Keep your recovery key; it resets your password.</p><form><label>ACCOUNT NAME<input name="username" autocomplete="username" minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+" required></label><label>PASSWORD<input name="password" type="password" autocomplete="current-password" minlength="10" maxlength="128" required></label><label class="recovery-label" hidden>RECOVERY KEY<input name="recoveryCode" autocomplete="off" maxlength="43"></label><div class="account-actions"><button type="submit" data-action="login">SIGN IN</button><button type="button" data-action="register">CREATE ACCOUNT</button><button type="button" data-action="recover">RECOVER ACCOUNT</button><button type="button" data-action="logout">PLAY AS GUEST</button></div></form><p class="account-status" role="status" aria-live="polite"></p><div class="recovery-result" hidden><p>Save this new recovery key in a safe place. Each key can reset the account only once.</p><textarea readonly aria-label="Your recovery key"></textarea><button type="button" data-action="save">DOWNLOAD RECOVERY KEY</button><button type="button" data-action="hide">I SAVED IT</button></div>`;
 const form=panel.querySelector('form'),status=panel.querySelector('.account-status'),result=panel.querySelector('.recovery-result');let lastRecovery=null,recovering=false,busy=false;
 async function request(action){if(busy)return;if(!form.reportValidity())return;busy=true;status.textContent='Connecting…';for(const b of form.querySelectorAll('button'))b.disabled=true;
  try{const base=new URL(endpoint());base.protocol=base.protocol==='wss:'?'https:':base.protocol==='ws:'?'http:':base.protocol;const response=await fetch(new URL('/api/account/'+action,base),{method:'POST',headers:{'Content-Type':'application/json',Authorization:getToken()?'Bearer '+getToken():''},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),body=await response.json();if(!response.ok)throw Error(body.error||'Account request failed');
   form.elements.password.value='';form.elements.recoveryCode.value='';setIdentity(body);status.textContent='SIGNED IN · '+body.profile.username+' · '+body.profile.xp+' XP';
   if(body.recoveryCode){lastRecovery={account:body.profile.username,recoveryKey:body.recoveryCode,server:base.origin};result.hidden=false;result.querySelector('textarea').value=body.recoveryCode;}else result.hidden=true;
  }catch(e){status.textContent=e.message;}finally{busy=false;for(const b of form.querySelectorAll('button'))b.disabled=false;}
 }
 form.addEventListener('submit',e=>{e.preventDefault();request(recovering?'recover':'login');});panel.addEventListener('click',async e=>{const action=e.target.dataset.action;if(!action)return;if(action==='register')await request('register');
  if(action==='recover'){recovering=!recovering;panel.querySelector('.recovery-label').hidden=!recovering;form.elements.recoveryCode.required=recovering;form.querySelector('[data-action="login"]').textContent=recovering?'RESET PASSWORD':'SIGN IN';form.elements.password.autocomplete=recovering?'new-password':'current-password';status.textContent=recovering?'Enter your recovery key and a new password.':'';}
  if(action==='logout'){try{const base=new URL(endpoint());base.protocol=base.protocol==='wss:'?'https:':'http:';await fetch(new URL('/api/account/logout',base),{method:'POST',headers:{Authorization:'Bearer '+(getToken()||'')},body:'{}'});}catch{}onLogout?.();status.textContent='Anonymous practice profile selected';result.hidden=true;lastRecovery=null;}
  if(action==='save'&&lastRecovery){const blob=new Blob([JSON.stringify(lastRecovery,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='TMINUS-'+lastRecovery.account+'-recovery.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  if(action==='hide'){result.hidden=true;result.querySelector('textarea').value='';lastRecovery=null;}
 });container.appendChild(panel);return panel;
}
